<?php require_once __DIR__.'/../app/bootstrap.php'; $u=require_login(); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$p=$_POST;$st=db()->prepare('INSERT INTO reading_plans(user_id,name,plan_type,start_date,end_date,target_count,description,status) VALUES(?,?,?,?,?,?,?,?)');$st->execute([$u['id'],$p['name'],$p['plan_type'],$p['start_date'],$p['end_date'],(int)$p['target_count'],$p['description']?:null,$p['status']]);redirect('plan_detail.php?id='.db()->lastInsertId());}$title='创建阅读计划';include __DIR__.'/../app/layout/header.php';?><div class="card"><form method="post"><?=csrf_field()?><div class="form-grid"><div><label>计划名称 *</label><input name="name" required placeholder="2026 年 5 月阅读计划"></div><div><label>计划类型</label><select name="plan_type"><option value="weekly">周度</option><option value="monthly" selected>月度</option><option value="quarterly">季度</option><option value="yearly">年度</option></select></div><div><label>状态</label><select name="status"><option value="not_started">未开始</option><option value="active" selected>进行中</option><option value="completed">已完成</option><option value="failed">未完成</option><option value="cancelled">已取消</option></select></div><div><label>开始日期</label><input type="date" name="start_date" required></div><div><label>结束日期</label><input type="date" name="end_date" required></div><div><label>目标读几本</label><input type="number" name="target_count" value="0"></div></div><p><label>说明</label><textarea name="description"></textarea></p><button>创建并进入详情</button></form></div><?php include __DIR__.'/../app/layout/footer.php';?>
